#!/bin/sh
# Builds Emerald Dash: graphics, caves and music are generated by the Python tools
# in tools/, then everything is compiled into build/emerald-dash.prg.
# Called by .vscode/run-current.sh with the compiler in $MEGA65_CC.

set -e
cd "$(dirname "$0")"
CC=${MEGA65_CC:-../toolchain/llvm-mos/bin/mos-mega65-clang}

mkdir -p build/gen
python3 tools/mkgfx.py build/gen build/preview.png
python3 tools/mkcave.py build/gen caves/*.cave
python3 tools/mkmusic.py build/gen
# shellcheck disable=SC2086
"$CC" -Os -g -Wall $EMERALD_CFLAGS -Isrc -Ibuild/gen -o build/emerald-dash.prg \
    -Wl,-Map=build/emerald-dash.map src/*.c build/gen/*.c
